Section CANSEC1. Context {rc : runConstT}.

Section CLA.
  Variables (ra sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  (* [comment removed for export] *)
  Variables (x1' x9' x11 x12 x17' x18 x21 x22 x23 x24 x25 x26 x27 x29 x30 x31 : word).
  Variables (m0 : amem) (RNG : footprint) (HW RK : Z) (ws : list Z).
  Variable Q : machine_state -> Prop.
  Hypothesis HWS : 1 <= zlen ws <= 255.
  Hypothesis HWB : Forall (fun c => 0 <= c < 256) ws.
  Hypothesis HHW : ablk HW (HW + 256).
  Hypothesis HRK : ablk RK (RK + 52).
  Hypothesis RK4 : RK mod 4 = 0.
  Hypothesis DHR : HW + 256 <= RK \/ RK + 52 <= HW.
  Hypothesis ZHW : zshadow m0 HW 256.
  Hypothesis ZRK : zshadow m0 RK 52.
  Hypothesis AWD : appW [(RK, RK + 52)].
  Hypothesis RHW : rng RNG HW 256.
  Hypothesis RHWs : rng RNG (shad HW) (nshad (256 + HW mod 8)).
  Hypothesis RRK : rng RNG RK 52.
  Hypothesis RRKs : rng RNG (shad RK) (nshad (52 + RK mod 8)).

  Ltac zbnd := unfold ABIT_MASK; rewrite ?land64_mod; rewrite ?Z.shiftl_mul_pow2 by lia; (try change (2^2) with 4);
    rewrite ?Z.mod_small by lia; lia.
  Ltac zck r ZS0 :=
    lazymatch goal with |- evtF _ _ _ (MS _ _ _ _ _ ?mm _) =>
    lazymatch goal with MU : munch ?W m0 mm |- _ =>
    let v := reg_val r in
    lazymatch v with Z_to_bv 64 (Z.shiftr ?a 3 + 2147450880) =>
      let RDB := fresh "RDB" in
      pose proof (chkZ mm _ _ a (zshadow_appW W m0 mm _ _ ZS0 MU AWD ltac:(lia) ltac:(lia)) ltac:(zbnd) ltac:(zbnd)) as RDB;
      zstep; rewrite ?sxb0; clear RDB
    end end end.

  (* [comment removed for export] *)
  Definition clA_inv (m1 : amem) (rank : list Z) : Prop :=
    u32arr asegs m1 RK (map (Z_to_bv 64) rank)
    /\ bytes_at asegs m1 HW (map (Z_to_bv 8) ws)
    /\ munch [(RK, RK + 52)] m0 m1 /\ wmono asegs m0 m1 /\ mem_inv asegs m1.

  (* [comment removed for export] *)
  Notation ST pc mm x5 x6 x7 x13 x14 x16 x28 :=
    (MS (mkR x1' sp gp tp x5 x6 x7 (Z_to_bv 64 RK) (Z_to_bv 64 (zlen ws)) (Z_to_bv 64 (-20)) x11 x12 x13 x14 x9' x16
             (Z_to_bv 64 1) x18 (Z_to_bv 64 HW) (Z_to_bv 64 2147450880) x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
        F (Z_to_bv 64 pc) fc None mm (seg_rom asegs)).

  Lemma clA_loop : forall f n rank wt m1 (x7 x14 x28 : word),
    Z.of_nat f = zlen ws - n -> 0 <= n < zlen ws ->
    RF_huf_rs_cl.cl_ok n rank wt -> clA_inv m1 rank ->
    (forall m2 rank' wt' (y7 y13 y14 y28 : word),
       collect_loop (skipn (Z.to_nat n) ws) rank wt = Ok (rank', wt') -> RF_huf_rs_cl.cl_ok (zlen ws) rank' wt' -> clA_inv m2 rank' ->
       evtF asegs RNG Q (ST 0x95380 m2 (Z_to_bv 64 12) (Z_to_bv 64 (zlen ws + 1)) y7 y13 y14 (Z_to_bv 64 wt') y28)) ->
    (forall m2 rank' (y6 y7 y13 y14 y16 y28 : word),
       collect_loop (skipn (Z.to_nat n) ws) rank wt = Err ZSTD_error_corruption_detected -> clA_inv m2 rank' ->
       evtF asegs RNG Q (ST 0x95560 m2 (Z_to_bv 64 12) y6 y7 y13 y14 y16 y28)) ->
